import {GOODS,THEMES,clone,hash,createGame,pick,remaining,visible,counts,rearrange,hint,tick,validateSave} from './engine.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const STORAGE='little-local:v1';
const CROPS=[[60,32,280,350],[398,52,318,318],[777,35,278,345],[1110,72,320,288],[60,390,280,313],[394,400,329,307],[744,410,364,295],[1116,379,307,330],[50,708,307,325],[407,705,309,324],[753,707,290,322],[1090,744,348,290]];
const icons={sound:'<path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8c2 2 2 6 0 8m3-11c4 4 4 10 0 14"/>',mute:'<path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="m16 9 5 6m0-6-5 6"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="var(--paper)"/><circle cx="16" cy="12" r="2" fill="var(--paper)"/><circle cx="10" cy="18" r="2" fill="var(--paper)"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]}</svg>`;}
export function good(type,extra=''){const r=CROPS[type];return `<span class="good ${extra}" aria-hidden="true"><svg viewBox="0 0 ${r[2]} ${r[3]}" focusable="false"><svg width="${r[2]}" height="${r[3]}" viewBox="${r.join(' ')}" overflow="hidden"><image href="./assets/goods-atlas.png" width="1448" height="1086" /></svg></svg></span>`;}
const easternDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const prettyDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const time=s=>`${Math.floor(Math.ceil(s)/60)}:${String(Math.ceil(s)%60).padStart(2,'0')}`;
const freshProfile=()=>({version:1,settings:{sound:false,motion:true,labels:false,theme:'market'},completed:0,totalMatches:0,bestCombo:0,dailyBest:{},sessions:{},mode:'cozy'});
let profile=freshProfile(),storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(saved?.version===1&&saved.sessions&&saved.settings){profile={...profile,...saved,settings:{...profile.settings,...saved.settings}};if(!THEMES[profile.settings.theme])profile.settings.theme='market';for(const k of ['completed','totalMatches','bestCombo'])if(!Number.isFinite(profile[k])||profile[k]<0)profile[k]=0;}}
catch{storageAvailable=false;}
let state,history=[],busy=false,paused=false,hintPicks=[],toastTimer,audioContext,lastTick=performance.now(),prevFocus;
const sessionKey=(mode,date=easternDate())=>mode==='daily'?`daily:${date}`:mode;
function save(){try{if(state)profile.sessions[sessionKey(state.mode,state.date)]={state,history:history.slice(-80)};profile.mode=state?.mode||'cozy';localStorage.setItem(STORAGE,JSON.stringify(profile));storageAvailable=true;}catch{storageAvailable=false;}$('#save-status').textContent=storageAvailable?'Your place is saved on this device ✓':'Playing without saving · browser storage unavailable';}
function make(mode,round=1){const date=easternDate();return createGame({mode,round:mode==='daily'?3:round,seed:mode==='daily'?hash('little-local:daily:v1:'+date):hash(`${Date.now()}:${Math.random()}:${round}`),theme:mode==='daily'?'market':profile.settings.theme,date});}
function loadMode(mode){
  if(!['cozy','daily','rush'].includes(mode))return;
  if(state)save();const entry=profile.sessions[sessionKey(mode)];
  if(entry&&validateSave(entry.state)){state=clone(entry.state);history=(entry.history||[]).filter(validateSave).slice(-80);}else{state=make(mode);history=[];}
  paused=false;hintPicks=[];lastTick=performance.now();closeModal();render();save();
  if(state.status==='won')showWin(false);else if(state.status==='timeout')showTimeout();
  else if(mode==='rush'&&!state.started)toast('Two easy minutes. The clock starts with your first tap.');
  else if(mode==='daily')toast(`${prettyDate(state.date)} · One shared board, as many tries as you like.`);
}
function newRound(mode=state.mode,replay=false){
  state=replay?createGame({mode:state.mode,round:state.round,seed:state.seed,theme:state.theme,date:state.date}):make(mode,state.mode===mode?state.round+1:1);
  history=[];hintPicks=[];paused=false;busy=false;lastTick=performance.now();closeModal();render();save();
}
function toast(message,duration=3200){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),duration);}
function announce(message){$('#announcer').textContent=message;}
function applySettings(){document.body.dataset.theme=profile.settings.theme;document.body.classList.toggle('reduce-motion',!profile.settings.motion);document.body.classList.toggle('labels',profile.settings.labels);$('#sound-button').innerHTML=icon(profile.settings.sound?'sound':'mute');$('#sound-button').ariaLabel=profile.settings.sound?'Turn sound off':'Turn sound on';$('#sound-button').title=profile.settings.sound?'Sound on':'Sound off';$('#settings-button').innerHTML=icon('settings');}
function render(){
  applySettings();
  $$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',b.dataset.mode===state.mode);});
  const theme=THEMES[profile.settings.theme];$('#shop-name').textContent=theme.name;$('#cabinet-sign').textContent=theme.sign;
  $('#round-label').textContent=state.mode==='daily'?'THE DAILY SORT':state.mode==='rush'?'A LIVELIER DELIVERY':'MORNING DELIVERY';
  $('#round-number').textContent=state.mode==='daily'?String(new Date(state.date+'T12:00:00').getDate()):String(state.round).padStart(2,'0');
  const names=['Fresh beginnings','A familiar rhythm','Room for good things','A little more local','A slower kind of lovely','Fresh from the market'];
  $('#round-name').textContent=state.mode==='daily'?prettyDate(state.date):names[(state.round-1)%names.length];
  const percent=Math.round(state.matches*3/state.total*100);
  $('#match-progress').textContent=`${state.matches} of ${state.total/3} matches`;$('#progress-percent').textContent=percent+'%';$('#progress-fill').style.width=percent+'%';$('.progress-track').setAttribute('aria-valuenow',percent);
  $('#stock-count').textContent=`${remaining(state)} little things`;$('#pace-copy').textContent=state.mode==='rush'?'A little hustle, just for fun.':state.mode==='daily'?'The same little puzzle for everyone.':'No clock. You’re right on time.';
  renderClock();
  $('#board').innerHTML=state.shelves.map((s,si)=>{
    const front=s.rows[0]||[],back=s.rows[1]||[],backCount=s.rows.slice(1).flat().filter(t=>t!==null).length;
    return `<div class="shelf" data-shelf="${si}" aria-label="Shelf ${si+1}${backCount?`, ${backCount} items behind`:''}">${backCount?`<div class="backstock">${back.filter(t=>t!==null).map(t=>good(t)).join('')}</div><span class="shelf-stock-number" aria-hidden="true">+${backCount}</span>`:''}${!front.length?'<span class="empty-shelf" aria-hidden="true">all tidy</span>':''}<div class="shelf-items">${Array.from({length:3},(_,slot)=>{
      const t=front[slot];return t==null?'<span class="item empty" aria-hidden="true"></span>':`<button class="item ${hintPicks.some(p=>p.shelf===si&&p.slot===slot)?'hinted':''}" data-shelf="${si}" data-slot="${slot}" data-type="${t}" data-short="${GOODS[t].short}" aria-label="${GOODS[t].name}, shelf ${si+1}, position ${slot+1}" ${state.tray.length>=7||state.status!=='playing'?'disabled':''}>${good(t)}</button>`;
    }).join('')}</div><span class="shelf-label" aria-hidden="true">${['01','02','03','04','05','06'][si]}</span></div>`;
  }).join('');
  $('#basket').innerHTML=Array.from({length:7},(_,i)=>`<div class="basket-slot" aria-label="${state.tray[i]===undefined?'Empty basket space':GOODS[state.tray[i]].name}">${state.tray[i]===undefined?'':good(state.tray[i])}</div>`).join('');
  $('#basket').classList.toggle('full',state.tray.length===7);$('#basket-count').textContent=state.tray.length+' / 7';
  $('#basket-message').textContent=state.tray.length===7?'A full basket. Undo or rearrange for free.':state.combo>1?`${state.combo} neat matches in a row. Lovely.`:'Tap 3 of a kind. Make a little room.';
  $('#undo-button').disabled=!history.length||state.status!=='playing';$('#hint-button').disabled=state.status!=='playing'||state.tray.length===7;$('#shuffle-button').disabled=state.status!=='playing';
  const cc=counts(state),used=GOODS.map((_,t)=>t).filter(t=>cc[t]>0);
  $('#legend').innerHTML=used.map(t=>`<button class="legend-row" data-legend="${t}" aria-label="Highlight ${GOODS[t].name}, ${cc[t]} remaining including hidden stock">${good(t)}<span>${GOODS[t].short}</span><span>${cc[t]}</span></button>`).join('')||'<p class="modal-copy">Every little thing, in its place.</p>';
  const stamps=profile.completed%3;$('#stamps').innerHTML=Array.from({length:3},(_,i)=>`<span class="stamp ${i<stamps?'filled':''}" aria-label="${i<stamps?'Collected':'Uncollected'} stamp">${i<stamps?'✿':'✳'}</span>`).join('');
  $('#stamps').ariaLabel=`${stamps} of 3 stamps toward your next shop chapter`;
  $('#stamp-copy').textContent=profile.completed?`${profile.completed} ${profile.completed===1?'delivery':'deliveries'} sorted. ${3-stamps} to your next chapter.`:'Every delivery adds a little love.';
  $('#footnote').textContent=state.mode==='daily'?`Burlington daily · ${prettyDate(state.date)} · Bests stay on this device.`:'Clear the front of a shelf to discover what’s tucked behind.';
}
function renderClock(){const rush=state.mode==='rush'&&!state.clockDisabled,badge=$('#pace-badge');badge.className='pace-badge'+(rush?' rush':'')+(rush&&state.seconds<30?' low':'');badge.innerHTML=rush?`<span aria-hidden="true">◷</span> ${remaining(state)<=3?'Last three · breathe':time(state.seconds)}`:state.mode==='daily'?'<span aria-hidden="true">☀</span> The daily sort':'<span aria-hidden="true">∞</span> Take your time';$('#pause-button').classList.toggle('show',rush);}
function snapshot(){history.push(clone(state));if(history.length>80)history.shift();}
function sound(match=false){if(!profile.settings.sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const notes=match?[523.25,659.25,783.99]:[329.63+state.tray.length*35];notes.forEach((f,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain(),start=audioContext.currentTime+i*.065;osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.045,start+.01);gain.gain.exponentialRampToValueAtTime(.001,start+.23);osc.connect(gain);gain.connect(audioContext.destination);osc.start(start);osc.stop(start+.25);});}catch{}}
function particles(x,y){if(!profile.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<15;i++){const el=document.createElement('span');el.className='particle';el.style.cssText=`left:${x}px;top:${y}px;background:${['#c99d5c','#789674','#b96b55','#e6c77e'][i%4]};--dx:${Math.random()*170-85}px;--dy:${Math.random()*-130+25}px;--rot:${Math.random()*360}deg`;document.body.append(el);setTimeout(()=>el.remove(),850);}}
async function choose(shelf,slot){
  if(busy||paused||$('#modal').open||state.status!=='playing'||state.tray.length>=7)return false;
  const button=$(`.item[data-shelf="${shelf}"][data-slot="${slot}"]`);if(!button)return false;
  const rect=button.getBoundingClientRect(),beforeRows=state.shelves.map(s=>s.rows.length);snapshot();const result=pick(state,shelf,slot);if(!result.ok){history.pop();return false;}
  hintPicks=hintPicks.filter(p=>!(p.shelf===shelf&&p.slot===slot));
  if(result.matched)hintPicks=[];
  sound(result.matched);render();save();
  for(let i=0;i<6;i++)if(state.shelves[i].rows.length<beforeRows[i]&&state.shelves[i].rows.length)$(`.shelf[data-shelf="${i}"]`).classList.add('revealed');
  const slots=$$('.basket-slot'),target=slots[Math.min(state.tray.length,6)].getBoundingClientRect();
  if(profile.settings.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const flying=document.createElement('div');flying.className='flying-good';flying.innerHTML=good(result.type);flying.style.cssText=`left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px`;flying.firstChild.style.cssText='width:100%;height:100%';document.body.append(flying);requestAnimationFrame(()=>requestAnimationFrame(()=>{flying.style.transform=`translate(${target.left-rect.left}px,${target.top-rect.top}px) scale(.6)`;flying.style.opacity='0';}));setTimeout(()=>flying.remove(),330);}
  if(result.matched){$('.basket-wrap').classList.remove('matched');requestAnimationFrame(()=>$('.basket-wrap').classList.add('matched'));particles(rect.left+rect.width/2,rect.top+rect.height/2);announce(`${GOODS[result.type].name} matched. ${state.matches} of ${state.total/3} matches.`);if(state.combo===3||state.combo===6)toast(state.combo===3?'Three lovely matches in a row.':'You’ve found your rhythm. Six in a row.');}
  else announce(`${GOODS[result.type].name} in your basket. ${state.tray.length} of 7 spaces used.`);
  if(result.full)toast('No worries. Undo a tap or rearrange for a fresh start.',5000);
  if(state.status==='won'){finishRound();showWin(true);}
  // Rerendered buttons preserve keyboard position at the next available shelf item.
  if(document.activeElement===document.body){const next=$(`.item[data-shelf="${shelf}"]:not(:disabled)`)||$('.item:not(:disabled)');next?.focus({preventScroll:true});}
  return true;
}
function undo(){if(!history.length||state.status!=='playing'||paused)return;const elapsed=state.elapsed,seconds=state.seconds,undos=state.undos+1;state=history.pop();state.elapsed=elapsed;state.seconds=seconds;state.undos=undos;hintPicks=[];lastTick=performance.now();render();save();toast('A little room to rethink.');}
function showHint(){if(paused||state.status!=='playing'||state.tray.length===7)return;const h=hint(state);if(h){hintPicks=h.picks;state.hints++;render();save();toast(`Look for ${GOODS[h.type].name.toLowerCase()}.`,3500);}else{toast('The next match is tucked away. Undo, or rearrange for free.',5000);}}
function doRearrange(){if(paused||state.status!=='playing')return;snapshot();rearrange(state);hintPicks=[];render();save();toast('Same little things. A fresh, solvable arrangement.');}
function finishRound(){
  if(state.rewarded)return;state.rewarded=true;profile.completed++;profile.totalMatches+=state.matches;profile.bestCombo=Math.max(profile.bestCombo,state.bestCombo);
  if(state.mode==='daily'){const current={moves:state.moves,helps:state.hints+state.rearranges+state.undos,score:state.score,seconds:Math.round(state.elapsed)},prior=profile.dailyBest[state.date];if(!prior||current.helps<prior.helps||current.helps===prior.helps&&current.score>prior.score||current.helps===prior.helps&&current.score===prior.score&&current.seconds<prior.seconds)profile.dailyBest[state.date]=current;}
  save();render();
}
function openModal(html){prevFocus=document.activeElement;$('#modal-content').innerHTML=html;$('#modal-close').hidden=state.status!=='playing';paused=true;lastTick=performance.now();if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();paused=false;lastTick=performance.now();}
function help(){openModal(`<div class="modal-eyebrow">WELCOME TO LITTLE LOCAL</div><h2 class="modal-title" id="modal-title">Good things come in threes.</h2><div class="modal-art">${good(0)}${good(0)}${good(0)}</div><ol class="steps"><li>Tap identical goods from any shelf. Three of a kind in your basket disappear.</li><li>Empty the front of a shelf to reveal its back stock. The faint goods give you a peek.</li><li>Your basket has seven spaces. If it fills up, Undo or Rearrange is always free.</li></ol><p class="modal-copy">Cozy and Daily have no timer. Rush starts on your first tap, pauses when you step away, and lets you finish the last three in peace.</p><button class="primary-button" data-action="close">Let’s make a little room</button><button class="secondary-button" data-action="settings">Sound & shop settings</button>`);}
function settings(){openModal(`<div class="modal-eyebrow">MAKE YOURSELF AT HOME</div><h2 class="modal-title" id="modal-title">Your kind of cozy.</h2><label class="settings-row"><span>Soft little sounds<small>A gentle note with each tap and match.</small></span><input type="checkbox" data-setting="sound" ${profile.settings.sound?'checked':''}></label><label class="settings-row"><span>A little movement<small>Scooting goods and a sprinkle of confetti.</small></span><input type="checkbox" data-setting="motion" ${profile.settings.motion?'checked':''}></label><label class="settings-row"><span>Names on the goods<small>Extra help telling everything apart.</small></span><input type="checkbox" data-setting="labels" ${profile.settings.labels?'checked':''}></label><div class="modal-eyebrow">A CHANGE OF SCENERY</div><div class="theme-options">${Object.entries(THEMES).map(([key,t])=>`<button class="theme-option ${profile.settings.theme===key?'selected':''}" data-theme-choice="${key}" aria-pressed="${profile.settings.theme===key}"><span class="swatch" style="background:${key==='bakery'?'#d7a571':key==='lakeside'?'#aec3b5':'#ddb385'}"></span><span>${t.name}<small>${key==='market'?'Maple, market flowers & familiar favorites':key==='bakery'?'Coffee, croissants & the morning sun':'Berries, lake breezes & a slower afternoon'}</small></span></button>`).join('')}</div><p class="modal-copy">Change the shop anytime. New deliveries bring its favorite goods; your current puzzle stays put.</p><button class="primary-button" data-action="close">Just right</button><button class="secondary-button" data-action="journal">Open your shop journal</button><button class="secondary-button" data-action="restart-confirm">Restart this delivery</button>`);}
function journal(){const best=profile.dailyBest[easternDate()];openModal(`<div class="modal-eyebrow">YOUR LITTLE LOCAL</div><h2 class="modal-title" id="modal-title">A little love adds up.</h2><div class="journal-stats"><div><strong>${profile.completed}</strong><span>deliveries sorted</span></div><div><strong>${profile.totalMatches}</strong><span>happy matches</span></div><div><strong>${profile.bestCombo}</strong><span>best chain</span></div></div><div class="stamps">${Array.from({length:3},(_,i)=>`<span class="stamp ${profile.completed%3>i?'filled':''}">${profile.completed%3>i?'✿':'✳'}</span>`).join('')}</div><p class="modal-copy">Chapter ${Math.floor(profile.completed/3)+1}: ${['The first little shelf','A familiar face','Part of the neighborhood','The good old days'][Math.floor(profile.completed/3)%4]}. ${3-profile.completed%3} more deliveries to fill this page.</p><p class="modal-copy">${best?`Today’s Daily best: ${best.moves} taps, ${best.helps} assists, ${time(best.seconds)}. Your records stay on this device.`:'Try the Daily for a fresh shared puzzle each day, on Burlington time. Your personal best is saved here.'}</p><button class="primary-button" data-action="close">Back to my little shop</button><button class="secondary-button" data-action="settings">Choose a shop</button>`);}
function showWin(celebrate){const perfect=state.hints+state.rearranges+state.undos===0;openModal(`<div class="win-emblem" aria-hidden="true">✿</div><div class="modal-eyebrow">${state.mode==='daily'?'TODAY’S DAILY, BEAUTIFULLY SORTED':'DELIVERY COMPLETE'}</div><h2 class="modal-title" id="modal-title">Everything in its place.</h2><p class="modal-copy">${state.mode==='cozy'?'Take a breath. There’s always another little delivery when you’re ready.':state.mode==='daily'?'Same shelves, your own little way through. Come back tomorrow for a fresh sort.':'A little bustle, a lovely finish. Time to enjoy the tidy shelves.'}</p>${perfect?'<span class="perfect">✧ An unassisted clear. Nicely done.</span>':''}<div class="win-stats"><div><strong>${state.matches}</strong><span>MATCHES</span></div><div><strong>${state.score}</strong><span>POINTS</span></div><div><strong>${state.bestCombo}×</strong><span>BEST CHAIN</span></div></div><button class="primary-button" data-action="${state.mode==='daily'?'share':'next'}">${state.mode==='daily'?'Copy my daily result':'Bring in the next delivery →'}</button>${state.mode==='daily'?'<button class="secondary-button" data-action="cozy">Keep playing in Cozy</button>':''}<button class="secondary-button" data-action="replay">Play this delivery again</button>`);if(celebrate){const r=$('#modal').getBoundingClientRect();particles(r.left+r.width/2,r.top+70);}}
function showTimeout(){openModal(`<div class="win-emblem" aria-hidden="true">◷</div><div class="modal-eyebrow">THAT WAS A LIVELY LITTLE RUSH</div><h2 class="modal-title" id="modal-title">A little more time?</h2><p class="modal-copy">You sorted ${state.matches} of ${state.total/3} matches. Finish this delivery without the clock, or give the same puzzle another go.</p><button class="primary-button" data-action="untimed">Keep this board, lose the clock</button><button class="secondary-button" data-action="replay">Try Rush again</button>`);}
function pause(){openModal('<div class="win-emblem" aria-hidden="true">☕</div><h2 class="modal-title" id="modal-title">The shop can wait.</h2><p class="modal-copy">Your shelves are right where you left them. The clock is paused.</p><button class="primary-button" data-action="close">I’m ready</button><button class="secondary-button" data-action="settings">Make yourself at home</button>');}
function restartConfirm(){openModal('<div class="modal-eyebrow">A FRESH START</div><h2 class="modal-title" id="modal-title">Restock this delivery?</h2><p class="modal-copy">This puts every item back in its original place. Your other deliveries and journal are saved.</p><button class="primary-button" data-action="replay">Yes, start this delivery again</button><button class="secondary-button" data-action="close">Keep my progress</button>');}
async function share(){const helps=state.hints+state.undos+state.rearranges;const result=`Little Local · ${state.date}\n${'🌿'.repeat(Math.min(6,Math.ceil(state.matches/3)))}\n${state.matches} matches · ${state.score} points · ${helps} assists\nA little Vermont state of mind.`;openModal(`<h2 class="modal-title" id="modal-title">Your daily sort.</h2><p class="modal-copy">A little calm to pass along. You can also select and copy the text below.</p><textarea aria-label="Your daily result" readonly rows="6" style="width:100%;font:inherit;font-size:14px;line-height:1.6;padding:14px;border:1px solid var(--line);border-radius:9px;background:#fffaf0;color:var(--ink)">${result}</textarea><button class="primary-button" data-action="share">Copy result text</button><button class="secondary-button" data-action="results">Back to results</button>`);try{await navigator.clipboard.writeText(result);toast('Your daily result is copied. Share a little calm.');}catch{toast('Select the result text to copy it.');$('#modal textarea').select();}}
$('#board').addEventListener('click',e=>{const b=e.target.closest('.item[data-slot]');if(b)choose(Number(b.dataset.shelf),Number(b.dataset.slot));});
$('#board').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;const b=e.target.closest('.item[data-slot]');if(!b)return;e.preventDefault();const buttons=$$('.item:not(:disabled)'),i=buttons.indexOf(b),delta=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:e.key==='ArrowDown'?6:-6;buttons[(i+delta+buttons.length)%buttons.length]?.focus();});
$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.mode!==state.mode)loadMode(b.dataset.mode);}));
$('#undo-button').addEventListener('click',undo);$('#hint-button').addEventListener('click',showHint);$('#shuffle-button').addEventListener('click',doRearrange);
$('#help-button').addEventListener('click',help);$('#settings-button').addEventListener('click',settings);$('#shop-button').addEventListener('click',settings);$('#journal-button').addEventListener('click',journal);$('#pause-button').addEventListener('click',pause);
$('#sound-button').addEventListener('click',()=>{profile.settings.sound=!profile.settings.sound;applySettings();sound(true);save();toast(profile.settings.sound?'A little sound, a little joy.':'A quiet little shop.');});
$('#legend-button').addEventListener('click',()=>toast('Counts include your basket and hidden stock. Tap a good to find visible ones.',5500));
$('#legend').addEventListener('click',e=>{const b=e.target.closest('[data-legend]');if(!b||state.status!=='playing')return;const type=Number(b.dataset.legend);hintPicks=visible(state).filter(p=>p.type===type);render();toast(hintPicks.length?`${hintPicks.length} ${GOODS[type].name.toLowerCase()} on the front shelves.`:`The ${GOODS[type].name.toLowerCase()} is tucked behind, or in your basket.`);});
$('#modal-close').addEventListener('click',closeModal);$('#modal').addEventListener('cancel',e=>{if(state.status!=='playing')e.preventDefault();});$('#modal').addEventListener('close',()=>{paused=false;lastTick=performance.now();prevFocus?.isConnected&&prevFocus.focus({preventScroll:true});});
$('#modal').addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){const action=a.dataset.action;({close:closeModal,settings,journal,'restart-confirm':restartConfirm,next:()=>newRound(),replay:()=>newRound(state.mode,true),cozy:()=>loadMode('cozy'),share,results:()=>showWin(false),untimed:()=>{state.status='playing';state.clockDisabled=true;history=[];closeModal();render();save();toast('All the time you need. Your Cozy delivery is saved separately.');}})[action]?.();}const theme=e.target.closest('[data-theme-choice]');if(theme&&THEMES[theme.dataset.themeChoice]){profile.settings.theme=theme.dataset.themeChoice;render();save();settings();}});
$('#modal').addEventListener('change',e=>{const key=e.target.dataset.setting;if(['sound','motion','labels'].includes(key)){profile.settings[key]=e.target.checked;applySettings();save();if(key==='sound')sound(true);}});
document.addEventListener('keydown',e=>{if($('#modal').open||/INPUT|TEXTAREA/.test(e.target.tagName))return;if(e.key.toLowerCase()==='u'){e.preventDefault();undo();}if(e.key.toLowerCase()==='h'){e.preventDefault();showHint();}if(e.code==='Space'&&e.target===document.body&&state.mode==='rush'){e.preventDefault();pause();}});
document.addEventListener('visibilitychange',()=>{lastTick=performance.now();if(document.hidden)save();else if(state.mode==='rush'&&state.started&&state.status==='playing'&&!$('#modal').open)pause();});
window.addEventListener('blur',()=>{if(state.mode==='rush'&&state.started&&state.status==='playing'&&!$('#modal').open)pause();});
window.addEventListener('pagehide',save);
setInterval(()=>{const now=performance.now(),delta=(now-lastTick)/1000;lastTick=now;if(paused||document.hidden)return;tick(state,Math.min(delta,1));renderClock();if(state.status==='timeout'&&!$('#modal').open){save();showTimeout();}},200);
setInterval(save,5000);
loadMode(['cozy','daily','rush'].includes(profile.mode)?profile.mode:'cozy');

// Optional WebMCP support. These actions use the same state and controls as play.
const context=document.modelContext;
if(context?.registerTool){
  const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  const read=()=>({mode:state.mode,round:state.round,status:state.status,paused,visible:visible(state).map(p=>({...p,name:GOODS[p.type].name})),basket:state.tray.map(t=>GOODS[t].name),matches:state.matches,totalMatches:state.total/3});
  for(const tool of [
    {name:'read_sorting_game',title:'Read the shelves',description:'Read the visible goods, basket, game mode, and progress without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:read},
    {name:'pick_sorting_goods',title:'Pick goods from the shelves',description:'Tap up to three currently visible goods in order, using the same matching rules as the board. Shelf and slot indices start at zero. Stops if the basket fills or the round ends.',inputSchema:{type:'object',properties:{picks:{type:'array',minItems:1,maxItems:3,items:{type:'object',properties:{shelf:{type:'integer',minimum:0,maximum:5},slot:{type:'integer',minimum:0,maximum:2}},required:['shelf','slot'],additionalProperties:false}}},required:['picks'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!Array.isArray(input?.picks)||input.picks.length<1||input.picks.length>3||input.picks.some(p=>!Number.isInteger(p.shelf)||p.shelf<0||p.shelf>5||!Number.isInteger(p.slot)||p.slot<0||p.slot>2))throw new Error('Provide 1–3 valid shelf and slot pairs.');if(paused||state.status!=='playing')throw new Error('Resume the game before picking goods.');let picked=0;for(const p of input.picks){if(!await choose(p.shelf,p.slot))break;picked++;}return {picked,...read()};}},
  ]){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
}
